// ============================================================================
// ENGLISH GRADE 6: skills, prerequisites and the misconception library (authoring source).
// Written offline by Claude (12 Nov 2026), no model call. Everything here is DRAFT until a
// Kenyan English teacher reviews it (docs/qa/english-g6-review-2026-11-12.md lists what to check).
// scripts/build-english-g6.mjs merges it into curriculum/english/g6.json (HOREB owns that file),
// then `npm run subject:map -- english 6 --dir english --title English` writes the in-app map.
// Sub-strand keys: 'GRAMMA.T1' = the sub-strand ENGL.G6.LANGUA.T1_* is written LANGUA here (the design's own code).
// A skill: S(sub, KEY, name, outcome letters, what the child does, forms, prerequisites, thinking).
// Prerequisites: 'G5:<SUB>.<KEY>' = a Grade 5 English skill (sub like 'GRAMMA.T5'); 'S:KEY' = a Grade 6 skill.
// LEADS: Grade 6 skill key -> Grade 7 English outcomes ('GRAMMA.T5.a' = the outcome of ENGL.G7.GRAMMA.T5_*) where the link is real.
// ============================================================================
export const TO_CONFIRM = 'common learner error; to confirm by a Kenyan English teacher';
export const KISWAHILI = 'Kiswahili influence (to confirm by a Kenyan English teacher)';
export const EAR = 'to confirm by a Kenyan English teacher: sound judgements depend on the accent the class is taught in';

const S = (sub, id, name, outcomes, does, forms, pre = [], thinking = ['recall']) => ({ sub, id, name, outcomes, mastery: does.endsWith('.') ? does : `${does}, in 8 of 10 new items.`, forms, pre, thinking });
const CH = 'choose the correct word', GAP = 'fill the gap', SPOT = 'spot the mistake', SENT = 'choose the correct sentence';

