// Outcomes that need a person or a task, not a question, with what each needs (W composition, O speaking, P practical, A attitude).
export const NOT_BUILT = [
  ['LANGUA.T3', 'Correlative conjunctions in speech (outcome b, oral half)', 'Using both ... and in conversation is heard, not tapped: the written half is tested by the families. Needs the speaking check.'],
  ['LISTEN.T6', 'Stress and intonation in questions, statements and exclamations (outcome c)', 'Stress is heard. Needs the speaking check with a teacher listening to a child read aloud. Written stress marks are not tested here, because the answer check cannot tell REcord from reCORD.'],
];

// ---------------------------------------------------------------- the misconception library
// M(skill, code, error, example question, wrong answer, right answer, help, feedback, source, cause)
const M = (skill, code, error, question, wrong, right, help, feedback, source = TO_CONFIRM, cause = 'Common error of Kenyan learners of English.') =>
  ({ skill, code, error, example: { question, wrong_answer: wrong, correct_answer: right }, cause, reveals: `Offer "${wrong}" next to the right answer in a new sentence and ask again.`, help, feedback, source });

